// ─── Domain Types ────────────────────────────────────────────────────────────

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

// ─── Project ─────────────────────────────────────────────────────────────────

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

// ─── Task ────────────────────────────────────────────────────────────────────

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

// ─── Comment ─────────────────────────────────────────────────────────────────

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
}

// ─── Notification ─────────────────────────────────────────────────────────────

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ─── Event Bus Payloads ───────────────────────────────────────────────────────

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ─── HTTP Helpers ─────────────────────────────────────────────────────────────

export interface ApiError {
  error: string;
}

// ─── Event Bus ───────────────────────────────────────────────────────────────
// In-memory publish/subscribe hub for inter-service communication.
// Services MUST NOT import each other; they communicate exclusively through here.

type EventCallback = (payload: unknown) => void;

class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /** Subscribe to a named event. Multiple subscribers per event are supported. */
  subscribe(event: string, callback: EventCallback): void {
    const existing = this.subscribers.get(event) ?? [];
    this.subscribers.set(event, [...existing, callback]);
  }

  /** Publish an event to all registered subscribers synchronously. */
  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) ?? [];
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        // Isolate subscriber errors so a bad handler cannot break the publisher
        console.error(`[EventBus] Error in subscriber for "${event}":`, err);
      }
    }
  }
}

// Singleton instance shared across the whole application
export const eventBus = new EventBus();

import { randomUUID } from 'crypto';
import type { User, CreateUserInput, UpdateUserInput } from '../types.js';

// ─── User Service ─────────────────────────────────────────────────────────────
// Owns the user store exclusively. No other service may read/write this store.

class UserService {
  private store: Map<string, User> = new Map();

  listUsers(): User[] {
    return Array.from(this.store.values());
  }

  getUser(id: string): User | undefined {
    return this.store.get(id);
  }

  createUser(input: CreateUserInput): User {
    const user: User = {
      id: randomUUID(),
      name: input.name,
      email: input.email,
    };
    this.store.set(user.id, user);
    return user;
  }

  updateUser(id: string, input: UpdateUserInput): User | undefined {
    const user = this.store.get(id);
    if (!user) return undefined;

    const updated: User = {
      ...user,
      ...(input.name !== undefined && { name: input.name }),
      ...(input.email !== undefined && { email: input.email }),
    };
    this.store.set(id, updated);
    return updated;
  }

  deleteUser(id: string): boolean {
    return this.store.delete(id);
  }
}

export const userService = new UserService();

import { randomUUID } from 'crypto';
import type { Project, CreateProjectInput, UpdateProjectInput } from '../types.js';

// ─── Project Service ──────────────────────────────────────────────────────────
// Owns the project store exclusively. No other service may read/write this store.

class ProjectService {
  private store: Map<string, Project> = new Map();

  listProjects(): Project[] {
    return Array.from(this.store.values());
  }

  getProject(id: string): Project | undefined {
    return this.store.get(id);
  }

  createProject(input: CreateProjectInput): Project {
    const project: Project = {
      id: randomUUID(),
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  updateProject(id: string, input: UpdateProjectInput): Project | undefined {
    const project = this.store.get(id);
    if (!project) return undefined;

    const updated: Project = {
      ...project,
      ...(input.name !== undefined && { name: input.name }),
      ...(input.description !== undefined && { description: input.description }),
    };
    this.store.set(id, updated);
    return updated;
  }

  deleteProject(id: string): boolean {
    return this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    if (project.memberIds.includes(userId)) {
      // Idempotent: already a member
      return project;
    }

    const updated: Project = {
      ...project,
      memberIds: [...project.memberIds, userId],
    };
    this.store.set(projectId, updated);
    return updated;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    const updated: Project = {
      ...project,
      memberIds: project.memberIds.filter((id) => id !== userId),
    };
    this.store.set(projectId, updated);
    return updated;
  }
}

export const projectService = new ProjectService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus.js';
import type {
  Task,
  TaskStatus,
  CreateTaskInput,
  UpdateTaskInput,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from '../types.js';

// ─── Task Service ─────────────────────────────────────────────────────────────
// Owns the task store exclusively. Publishes events to the Event Bus for
// cross-service communication. Does NOT call other services directly.

/** Forward-only status transition table */
const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ['in-progress'],
  'in-progress': ['done'],
  done: [],
};

export type ChangeStatusResult =
  | { ok: true; task: Task }
  | { ok: false; reason: 'not_found' | 'invalid_transition' };

class TaskService {
  private store: Map<string, Task> = new Map();

  listByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId,
    );
  }

  getTask(id: string): Task | undefined {
    return this.store.get(id);
  }

  createTask(input: CreateTaskInput): Task {
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  updateTask(id: string, input: UpdateTaskInput): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const updated: Task = {
      ...task,
      ...(input.title !== undefined && { title: input.title }),
      ...(input.description !== undefined && { description: input.description }),
    };
    this.store.set(id, updated);
    return updated;
  }

  deleteTask(id: string): boolean {
    return this.store.delete(id);
  }

  changeStatus(id: string, newStatus: TaskStatus): ChangeStatusResult {
    const task = this.store.get(id);
    if (!task) return { ok: false, reason: 'not_found' };

    const allowed = VALID_TRANSITIONS[task.status];
    if (!allowed.includes(newStatus)) {
      return { ok: false, reason: 'invalid_transition' };
    }

    const oldStatus = task.status;
    const updated: Task = { ...task, status: newStatus };
    this.store.set(id, updated);

    // Publish status-change event so NotificationService can react
    const payload: TaskStatusChangedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId: updated.assigneeId,
      oldStatus,
      newStatus,
    };
    eventBus.publish('task.statusChanged', payload);

    return { ok: true, task: updated };
  }

  assignTask(id: string, assigneeId: string): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const updated: Task = { ...task, assigneeId };
    this.store.set(id, updated);

    // Publish assignment event so NotificationService can react
    const payload: TaskAssignedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId,
    };
    eventBus.publish('task.assigned', payload);

    return updated;
  }
}

export const taskService = new TaskService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus.js';
import type { Comment, CreateCommentInput, CommentAddedPayload } from '../types.js';

// ─── Comment Service ──────────────────────────────────────────────────────────
// Owns the comment store exclusively. Publishes events to the Event Bus.
// Does NOT call other services directly.
//
// NOTE: The router is responsible for resolving cross-service data (e.g. task
// title, author name) before calling createComment, because services are
// forbidden from calling each other.

export interface CreateCommentEnriched extends CreateCommentInput {
  /** Task title resolved by the router before calling this service */
  taskTitle: string;
  /** Author display name resolved by the router before calling this service */
  authorName: string;
}

class CommentService {
  private store: Map<string, Comment> = new Map();

  listByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) => c.taskId === taskId);
  }

  getComment(id: string): Comment | undefined {
    return this.store.get(id);
  }

  createComment(input: CreateCommentEnriched): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    // Publish event so NotificationService can react
    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle,
      authorId: comment.authorId,
      authorName: input.authorName,
    };
    eventBus.publish('comment.added', payload);

    return comment;
  }

  deleteComment(id: string): boolean {
    return this.store.delete(id);
  }
}

export const commentService = new CommentService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus.js';
import type {
  Notification,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from '../types.js';

// ─── Notification Service ─────────────────────────────────────────────────────
// Owns the notification store exclusively. Reacts to events from the Event Bus.
// Does NOT call other services directly.

class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor() {
    // Wire up event subscriptions at construction time.
    // The service is self-contained: it registers its own handlers.
    eventBus.subscribe('task.assigned', (payload) => {
      this.onTaskAssigned(payload as TaskAssignedPayload);
    });

    eventBus.subscribe('task.statusChanged', (payload) => {
      this.onTaskStatusChanged(payload as TaskStatusChangedPayload);
    });

    eventBus.subscribe('comment.added', (payload) => {
      this.onCommentAdded(payload as CommentAddedPayload);
    });
  }

  // ── Event Handlers ──────────────────────────────────────────────────────────

  private onTaskAssigned(payload: TaskAssignedPayload): void {
    this.createNotification(
      payload.assigneeId,
      `You have been assigned to task "${payload.taskTitle}" (${payload.taskId}).`,
    );
  }

  private onTaskStatusChanged(payload: TaskStatusChangedPayload): void {
    // Only notify if there is an assignee on the task
    if (!payload.assigneeId) return;

    this.createNotification(
      payload.assigneeId,
      `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`,
    );
  }

  private onCommentAdded(payload: CommentAddedPayload): void {
    // Notify the author that their comment was recorded
    // (In a real system you'd notify the task owner/assignee instead,
    //  but we only have the authorId available without cross-service lookup.)
    this.createNotification(
      payload.authorId,
      `${payload.authorName} commented on task "${payload.taskTitle}": comment ${payload.commentId}.`,
    );
  }

  // ── Public API ──────────────────────────────────────────────────────────────

  listForUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) => n.userId === userId);
  }

  markRead(id: string): Notification | undefined {
    const notification = this.store.get(id);
    if (!notification) return undefined;

    const updated: Notification = { ...notification, read: true };
    this.store.set(id, updated);
    return updated;
  }

  // ── Private helpers ─────────────────────────────────────────────────────────

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }
}

export const notificationService = new NotificationService();

import type { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';

import { userService } from './services/user-service.js';
import { projectService } from './services/project-service.js';
import { taskService } from './services/task-service.js';
import { commentService } from './services/comment-service.js';
import { notificationService } from './services/notification-service.js';
import type { TaskStatus } from './types.js';

// ─── Helpers ──────────────────────────────────────────────────────────────────

function send(res: ServerResponse, status: number, body: unknown): void {
  const json = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(json),
  });
  res.end(json);
}

function sendError(res: ServerResponse, status: number, message: string): void {
  send(res, status, { error: message });
}

/** Read and parse the request body as JSON. Rejects on parse error. */
function readBody<T = unknown>(req: IncomingMessage): Promise<T> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf-8');
      if (!raw) {
        resolve({} as T);
        return;
      }
      try {
        resolve(JSON.parse(raw) as T);
      } catch {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', reject);
  });
}

/** Extract path segments, ignoring leading/trailing slashes. */
function segments(pathname: string): string[] {
  return pathname.replace(/^\/|\/$/g, '').split('/');
}

// ─── Router ───────────────────────────────────────────────────────────────────

export async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse,
): Promise<void> {
  const baseUrl = `http://${req.headers.host ?? 'localhost'}`;
  const url = new URL(req.url ?? '/', baseUrl);
  const method = req.method ?? 'GET';
  const parts = segments(url.pathname);

  try {
    // ── /users ──────────────────────────────────────────────────────────────

    if (parts[0] === 'users') {
      // GET /users
      if (parts.length === 1 && method === 'GET') {
        return send(res, 200, userService.listUsers());
      }

      // POST /users
      if (parts.length === 1 && method === 'POST') {
        const body = await readBody<{ name?: string; email?: string }>(req);
        if (!body.name || !body.email) {
          return sendError(res, 400, 'name and email are required');
        }
        const user = userService.createUser({ name: body.name, email: body.email });
        return send(res, 201, user);
      }

      // /users/:id
      if (parts.length === 2) {
        const id = parts[1];

        // GET /users/:id
        if (method === 'GET') {
          const user = userService.getUser(id);
          if (!user) return sendError(res, 404, 'User not found');
          return send(res, 200, user);
        }

        // PUT /users/:id
        if (method === 'PUT') {
          const body = await readBody<{ name?: string; email?: string }>(req);
          const user = userService.updateUser(id, body);
          if (!user) return sendError(res, 404, 'User not found');
          return send(res, 200, user);
        }

        // DELETE /users/:id
        if (method === 'DELETE') {
          const deleted = userService.deleteUser(id);
          if (!deleted) return sendError(res, 404, 'User not found');
          res.writeHead(204);
          return res.end();
        }
      }
    }

    // ── /projects ────────────────────────────────────────────────────────────

    if (parts[0] === 'projects') {
      // GET /projects
      if (parts.length === 1 && method === 'GET') {
        return send(res, 200, projectService.listProjects());
      }

      // POST /projects
      if (parts.length === 1 && method === 'POST') {
        const body = await readBody<{ name?: string; description?: string }>(req);
        if (!body.name || !body.description) {
          return sendError(res, 400, 'name and description are required');
        }
        const project = projectService.createProject({
          name: body.name,
          description: body.description,
        });
        return send(res, 201, project);
      }

      // /projects/:id
      if (parts.length === 2) {
        const id = parts[1];

        // GET /projects/:id
        if (method === 'GET') {
          const project = projectService.getProject(id);
          if (!project) return sendError(res, 404, 'Project not found');
          return send(res, 200, project);
        }

        // PUT /projects/:id
        if (method === 'PUT') {
          const body = await readBody<{ name?: string; description?: string }>(req);
          const project = projectService.updateProject(id, body);
          if (!project) return sendError(res, 404, 'Project not found');
          return send(res, 200, project);
        }

        // DELETE /projects/:id
        if (method === 'DELETE') {
          const deleted = projectService.deleteProject(id);
          if (!deleted) return sendError(res, 404, 'Project not found');
          res.writeHead(204);
          return res.end();
        }
      }

      // /projects/:id/members
      if (parts.length === 3 && parts[2] === 'members') {
        const projectId = parts[1];

        // POST /projects/:id/members  — add member
        if (method === 'POST') {
          const body = await readBody<{ userId?: string }>(req);
          if (!body.userId) return sendError(res, 400, 'userId is required');
          const project = projectService.addMember(projectId, body.userId);
          if (!project) return sendError(res, 404, 'Project not found');
          return send(res, 200, project);
        }

        // DELETE /projects/:id/members  — remove member
        if (method === 'DELETE') {
          const body = await readBody<{ userId?: string }>(req);
          if (!body.userId) return sendError(res, 400, 'userId is required');
          const project = projectService.removeMember(projectId, body.userId);
          if (!project) return sendError(res, 404, 'Project not found');
          return send(res, 200, project);
        }
      }
    }

    // ── /tasks ───────────────────────────────────────────────────────────────

    if (parts[0] === 'tasks') {
      // GET /tasks?projectId=...
      if (parts.length === 1 && method === 'GET') {
        const projectId = url.searchParams.get('projectId');
        if (!projectId) return sendError(res, 400, 'projectId query parameter is required');
        return send(res, 200, taskService.listByProject(projectId));
      }

      // POST /tasks
      if (parts.length === 1 && method === 'POST') {
        const body = await readBody<{
          title?: string;
          description?: string;
          projectId?: string;
        }>(req);
        if (!body.title || !body.description || !body.projectId) {
          return sendError(res, 400, 'title, description and projectId are required');
        }
        const task = taskService.createTask({
          title: body.title,
          description: body.description,
          projectId: body.projectId,
        });
        return send(res, 201, task);
      }

      // /tasks/:id
      if (parts.length === 2) {
        const id = parts[1];

        // GET /tasks/:id
        if (method === 'GET') {
          const task = taskService.getTask(id);
          if (!task) return sendError(res, 404, 'Task not found');
          return send(res, 200, task);
        }

        // PUT /tasks/:id
        if (method === 'PUT') {
          const body = await readBody<{ title?: string; description?: string }>(req);
          const task = taskService.updateTask(id, body);
          if (!task) return sendError(res, 404, 'Task not found');
          return send(res, 200, task);
        }

        // DELETE /tasks/:id
        if (method === 'DELETE') {
          const deleted = taskService.deleteTask(id);
          if (!deleted) return sendError(res, 404, 'Task not found');
          res.writeHead(204);
          return res.end();
        }
      }

      // /tasks/:id/status
      if (parts.length === 3 && parts[2] === 'status') {
        const id = parts[1];

        // PUT /tasks/:id/status
        if (method === 'PUT') {
          const body = await readBody<{ status?: string }>(req);
          const validStatuses: TaskStatus[] = ['todo', 'in-progress', 'done'];
          if (!body.status || !validStatuses.includes(body.status as TaskStatus)) {
            return sendError(res, 400, 'status must be one of: todo, in-progress, done');
          }
          const result = taskService.changeStatus(id, body.status as TaskStatus);
          if (!result.ok) {
            if (result.reason === 'not_found') return sendError(res, 404, 'Task not found');
            return sendError(
              res,
              400,
              `Invalid status transition to "${body.status}". Status can only move forward: todo → in-progress → done.`,
            );
          }
          return send(res, 200, result.task);
        }
      }

      // /tasks/:id/assign
      if (parts.length === 3 && parts[2] === 'assign') {
        const id = parts[1];

        // PUT /tasks/:id/assign
        if (method === 'PUT') {
          const body = await readBody<{ assigneeId?: string }>(req);
          if (!body.assigneeId) return sendError(res, 400, 'assigneeId is required');
          const task = taskService.assignTask(id, body.assigneeId);
          if (!task) return sendError(res, 404, 'Task not found');
          return send(res, 200, task);
        }
      }
    }

    // ── /comments ────────────────────────────────────────────────────────────

    if (parts[0] === 'comments') {
      // GET /comments?taskId=...
      if (parts.length === 1 && method === 'GET') {
        const taskId = url.searchParams.get('taskId');
        if (!taskId) return sendError(res, 400, 'taskId query parameter is required');
        return send(res, 200, commentService.listByTask(taskId));
      }

      // POST /comments
      if (parts.length === 1 && method === 'POST') {
        const body = await readBody<{
          taskId?: string;
          authorId?: string;
          body?: string;
        }>(req);
        if (!body.taskId || !body.authorId || !body.body) {
          return sendError(res, 400, 'taskId, authorId and body are required');
        }

        // The router is the ONLY place allowed to do cross-service data lookup.
        // CommentService needs taskTitle and authorName for its event payload,
        // so we resolve them here before delegating to the service.
        const task = taskService.getTask(body.taskId);
        if (!task) return sendError(res, 404, 'Task not found');

        const author = userService.getUser(body.authorId);
        if (!author) return sendError(res, 404, 'Author (user) not found');

        const comment = commentService.createComment({
          taskId: body.taskId,
          authorId: body.authorId,
          body: body.body,
          taskTitle: task.title,
          authorName: author.name,
        });
        return send(res, 201, comment);
      }

      // /comments/:id
      if (parts.length === 2) {
        const id = parts[1];

        // GET /comments/:id
        if (method === 'GET') {
          const comment = commentService.getComment(id);
          if (!comment) return sendError(res, 404, 'Comment not found');
          return send(res, 200, comment);
        }

        // DELETE /comments/:id
        if (method === 'DELETE') {
          const deleted = commentService.deleteComment(id);
          if (!deleted) return sendError(res, 404, 'Comment not found');
          res.writeHead(204);
          return res.end();
        }
      }
    }

    // ── /notifications ────────────────────────────────────────────────────────

    if (parts[0] === 'notifications') {
      // GET /notifications?userId=...
      if (parts.length === 1 && method === 'GET') {
        const userId = url.searchParams.get('userId');
        if (!userId) return sendError(res, 400, 'userId query parameter is required');
        return send(res, 200, notificationService.listForUser(userId));
      }

      // PUT /notifications/:id/read
      if (parts.length === 3 && parts[2] === 'read' && method === 'PUT') {
        const id = parts[1];
        const notification = notificationService.markRead(id);
        if (!notification) return sendError(res, 404, 'Notification not found');
        return send(res, 200, notification);
      }
    }

    // ── 404 fallthrough ───────────────────────────────────────────────────────
    return sendError(res, 404, `Cannot ${method} ${url.pathname}`);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Internal server error';
    return sendError(res, 500, message);
  }
}

