// ─── Mini HTTP Client ─────────────────────────────────────────────────────────

interface Response<T = unknown> {
  status: number;
  body: T;
}

function request<T = unknown>(
  method: string,
  url: string,
  payload?: unknown,
): Promise<Response<T>> {
  return new Promise((resolve, reject) => {
    const { hostname, port, pathname, search } = new URL(url);
    const bodyStr = payload !== undefined ? JSON.stringify(payload) : undefined;

    const req = (await import('http')).default
      ? undefined // never used — see below
      : undefined;

    // Use the built-in http module directly
    import('http').then(({ request: httpRequest }) => {
      const options = {
        hostname,
        port: Number(port),
        path: pathname + search,
        method,
        headers: {
          'Content-Type': 'application/json',
          ...(bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
        },
      };

      const clientReq = httpRequest(options, (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (c: Buffer) => chunks.push(c));
        res.on('end', () => {
          const raw = Buffer.concat(chunks).toString('utf-8');
          let body: T;
          try {
            body = JSON.parse(raw) as T;
          } catch {
            body = raw as unknown as T;
          }
          resolve({ status: res.statusCode ?? 0, body });
        });
      });

      clientReq.on('error', reject);
      if (bodyStr) clientReq.write(bodyStr);
      clientReq.end();
    });
  });
}

